const JUDGE_BY_ID = Object.fromEntries(JUDGES.map(j=>[j.id, j]));

/* ---- atributos ---- */
// Generador con semilla (mulberry32) para que la conversión nivel → atributos sea la misma en todas las partidas
function seedOf(str){ let h=2166136261; for(const ch of String(str)){ h^=ch.charCodeAt(0); h=Math.imul(h,16777619); } return h>>>0; }
function seededRandom(seed){ let a=seed>>>0; return function(){ a=(a+0x6D2B79F5)>>>0; let t=a; t=Math.imul(t^(t>>>15), t|1); t^=t+Math.imul(t^(t>>>7), t|61); return ((t^(t>>>14))>>>0)/4294967296; }; }
function seededGauss(rnd){ let u=0,v=0; while(!u) u=rnd(); while(!v) v=rnd(); return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v); }
function nivelFromAttrs(at){ return Math.round(ATTR_KEYS.reduce((s,k)=>s+(at[k]||0),0)/ATTR_KEYS.length); }
// Convierte un nivel y un estilo en los cinco atributos. La media redondeada es exactamente el nivel.
function attrsFromNivel(nivel, style, seed){
  const bias=STYLE_ATTR_BIAS[style]||{}; const rnd=seededRandom(seedOf(seed||'')^seedOf(style||''));
  const raw=ATTR_KEYS.map(k=>(bias[k]||0)+seededGauss(rnd)*ATTR_NOISE);
  const mean=raw.reduce((a,b)=>a+b,0)/raw.length;
  const at={}; ATTR_KEYS.forEach((k,i)=>at[k]=clamp(Math.round(nivel+raw[i]-mean),1,ATTR_MAX));
  for(let guard=0; guard<20 && nivelFromAttrs(at)!==nivel; guard++){   // el recorte a 1-ATTR_MAX puede mover la media: se corrige
    const up=nivelFromAttrs(at)<nivel; const k=ATTR_KEYS.slice().sort((a,b)=>up? at[a]-at[b] : at[b]-at[a])[0]; at[k]=clamp(at[k]+(up?1:-1),1,ATTR_MAX); }
  return at;
}
function ensureAttrs(f){ if(!f) return f; if(!f.attrs || ATTR_KEYS.some(k=>typeof f.attrs[k]!=='number')) f.attrs=attrsFromNivel(f.nivel, styleOf(f), f.name); if(nivelFromAttrs(f.attrs)!==f.nivel) setNivel(f, f.nivel); return f; }
// Cambia el nivel de un freestyler desplazando sus cinco atributos por igual (conservan su forma) hasta que la media sea exactamente n
function setNivel(f, n){
  n=clamp(Math.round(n),1,99);
  if(!f.attrs || ATTR_KEYS.some(k=>typeof f.attrs[k]!=='number')){ f.attrs=attrsFromNivel(n, styleOf(f), f.name); f.nivel=n; return f; }
  const mean=ATTR_KEYS.reduce((s,k)=>s+f.attrs[k],0)/ATTR_KEYS.length; const d=n-mean;
  ATTR_KEYS.forEach(k=>f.attrs[k]=clamp(Math.round(f.attrs[k]+d),1,ATTR_MAX));
  for(let guard=0; guard<40 && nivelFromAttrs(f.attrs)!==n; guard++){   // el redondeo o el tope pueden desviar la media: se corrige
    const up=nivelFromAttrs(f.attrs)<n; const k=ATTR_KEYS.slice().sort((a,b)=>up? f.attrs[a]-f.attrs[b] : f.attrs[b]-f.attrs[a])[0]; f.attrs[k]=clamp(f.attrs[k]+(up?1:-1),1,ATTR_MAX); }
  f.nivel=n; return f;
}
function attrOf(f,k){ return (f && f.attrs && typeof f.attrs[k]==='number') ? f.attrs[k] : (f ? f.nivel : 50); }
function attrShown(f,k){ return Math.min(ATTR_SHOWN_MAX, Math.round(attrOf(f,k))); }   // para la interfaz: nunca por encima de 99
// Base de rendimiento en una ronda: media ponderada de los atributos según el tipo de ronda
// Fatiga del jugador en la batalla (fase D1): solo jugador:true; el resto del pool no tiene fatiga
function fatigaMod(F){ if(!F || !F.jugador) return 0; const x=F.fatiga||0; if(x>=FATIGA_ALTA) return -FATIGA_PENAL*Math.min(1,(x-FATIGA_ALTA)/(100-FATIGA_ALTA)); if(x<=FATIGA_BAJA) return FATIGA_BONUS; return 0; }
function roundBase(f, rt){ const w=ROUND_WEIGHTS[rt]||ROUND_WEIGHTS.min; return ATTR_KEYS.reduce((s,k)=>s+attrOf(f,k)*w[k],0); }
function mentalFactor(f){ return clamp(MENTAL_VAR_BASE - attrOf(f,'mentalidad')*MENTAL_VAR_SLOPE, 0.5, 1.5); }

/* ---- jueces ---- */
function judgesByGroup(g){ return JUDGES.filter(j=>j.country===g); }
// Sortea los jueces de una liga para una temporada: 4 del país + 1 internacional (ligas sin país: 5 internacionales)
// key: clave de liga (fms_espana…) o nombre de país (España, Argentina…). Sin grupo de jueces → 5 internacionales
function pickJudges(key){
  const grp=JUDGE_GROUP[key] || (Object.values(JUDGE_GROUP).includes(key) ? key : null); const pool=grp ? judgesByGroup(grp) : [];
  const intl=judgesByGroup('Internacional').slice().sort(()=>Math.random()-0.5);
  const loc=pool.slice().sort(()=>Math.random()-0.5);
  const nIntl = pool.length ? JUDGES_INTL_PER_LEAGUE : JUDGES_PER_LEAGUE;
  return [...loc.slice(0, JUDGES_PER_LEAGUE-nIntl), ...intl.slice(0, nIntl)].sort(()=>Math.random()-0.5).map(j=>j.id);
}
// Jueces de un torneo (Red Bull nacional, Under…): 4 del país del evento + 1 internacional; sin país con jueces, 5 internacionales
function tourneyJudges(countries){ const c=(countries||[]).find(x=>Object.values(JUDGE_GROUP).includes(x)); return pickJudges(c||null); }
function judgesOf(L){ if(!L) return pickJudges(null); if(!Array.isArray(L.judges) || L.judges.length!==JUDGES_PER_LEAGUE || L.judges.some(id=>!JUDGE_BY_ID[id])) L.judges=pickJudges(L.key); return L.judges; }
// Cuánto suma o resta un juez a la nota de un freestyler por sus gustos (escala 1-10)
function judgeTaste(j, f){ if(!j||!j.gustos) return 0; return Object.entries(j.gustos).reduce((s,[k,g])=>s+g*((attrOf(f,k)-50)/10)*JUDGE_TASTE_PER_10, 0); }
function judgeNoise(j){ const c=j ? clamp(j.consistencia,0,1) : 0.5; return JUDGE_NOISE_MAX-(JUDGE_NOISE_MAX-JUDGE_NOISE_MIN)*c; }
function judgeName(id){ const j=JUDGE_BY_ID[id]; return j ? j.name : `Juez ${id||''}`.trim(); }

/* ---- carrera y progresión (fase 5) ---- */
// Experiencia (años de carrera) y potencial (techo del nivel), estimados una vez de forma determinista por nombre
const EXP_LEGEND = [10, 14];        // leyendas
const EXP_VETERAN = [9, 12];        // fama muy por encima del nivel: famoso que ya no rinde
const EXP_YOUNG = [1, 3];           // nivel muy por encima de la fama: bueno y poco conocido
const EXP_MID = [5, 8];             // resto (madurez desde el primer año)
const EXP_CUSTOM = [2, 4];          // competidores propios
const EXP_FAMA_GAP = 10;            // fama − nivel ≥ +10 → veterano · nivel − fama ≥ 20 → joven
const EXP_NIVEL_GAP = 20;
const POT_YOUNG = [6, 14], POT_MID = [1, 4], POT_VET = [0, 0];   // margen de potencial sobre el nivel según etapa
const POT_MAX = 97, NIVEL_MIN = 35, NIVEL_MAX = 97;
// Etapas por experiencia
const EXP_YOUNG_MAX = 4, EXP_MID_MAX = 9;   // 0-4 joven · 5-9 madurez · 10+ veterano
// Progresión anual por atributo (puntos)
const GROW_RATE = 0.28;             // joven: sube esta fracción del margen hasta el potencial (por atributo, ponderado)
const GROW_MIN = 1, GROW_MAX = 3;   // joven: subida mínima y máxima por atributo cuando hay margen
const GROW_WEIGHT = {punchline:1.0, metrica:1.25, flow:1.25, impro:0.9, mentalidad:0.8};   // flow y métrica crecen antes
const MID_NOISE = 1;                // madurez: ruido uniforme de −1 a +1
const GROW_MID_RATE = 0.25;         // madurez: si queda más de GROW_MID_SLACK hasta el potencial, sube esta fracción del exceso (las promesas siguen creciendo)
const GROW_MID_SLACK = 4;           // madurez: holgura que no se recupera (quien está a 4 o menos de su potencial se comporta como antes: solo ruido)
const GROW_MID_MAX = 3;             // madurez: subida máxima por atributo y año
const DECLINE_START = 0.3;          // veterano: bajada el primer año tras EXP_MID_MAX
const DECLINE_STEP = 0.1;           // y crece esto cada año más
const DECLINE_MAX = 1.5;            // sin pasar de aquí
const DECLINE_WEIGHT = {punchline:0.8, metrica:1.0, flow:1.0, impro:0.5, mentalidad:0.5};   // la experiencia sostiene impro y mentalidad
const EXP_SUPPORT = 0.3;            // impro y mentalidad suben esto cada año (todas las etapas) hasta EXP_SUPPORT_CAP
const EXP_SUPPORT_CAP = 95;
const INACTIVE_PENALTY = 0.3;       // no compitió en nada esa temporada
const BOOST_CHAMPION = 0.8, BOOST_RUNNERUP = 0.5, BOOST_INTL = 0.8;   // empujones de fin de temporada (menores que el declive máximo: no lo anulan)
const BOOST_OVER_POT = 2;           // los empujones pueden superar el potencial como mucho en esto
const EVOL_TOP = 5;                 // cuántos salen en el resumen (los que más suben y más bajan)
// Retiros de fin de temporada (fase 6). Probabilidad anual = RET_BASE + RET_PER_YEAR·(exp − RET_EXP_MIN) − RET_NIVEL_SLOPE·(nivel − RET_NIVEL_REF)
const RET_EXP_MIN = 10;             // nadie se retira con menos años de carrera
const RET_BASE = 0.04;              // probabilidad al cumplir RET_EXP_MIN
const RET_PER_YEAR = 0.03;          // y sube esto por cada año más
const RET_NIVEL_REF = 75, RET_NIVEL_SLOPE = 0.005;   // −0,5 % por cada punto de nivel sobre 75 (+0,5 % por cada punto por debajo)
const RET_MAX = 0.6;                // tope de la probabilidad anual
const RET_LEGEND_MULT = 0.5;        // las leyendas aguantan el doble
// Nuevos talentos: tantos como retirados, dentro de este rango. Cada retirado deja su hueco en su país.
const NOVATO_MIN = 4, NOVATO_MAX = 50;   // el pool inicial tiene edades parecidas y se retira en oleada: el tope debe absorberla
const NOVATO_EXP = [0, 2];          // años de carrera al debutar
const NOVATO_NIVEL = [55, 75], NOVATO_NIVEL_MEDIA = 68, NOVATO_NIVEL_SD = 4;
const NOVATO_FAMA = [15, 40];
const NOVATO_PROMESA = 0.12;        // fracción con potencial alto
const POT_PROMESA = [88, 97];       // potencial de las promesas
const POT_NOVATO = [6, 14];         // margen de potencial sobre el nivel del resto de novatos (como los jóvenes de hoy; las promesas usan POT_PROMESA)
// Modo carrera: creación del freestyler del jugador
const CARRERA_PUNTOS = 300, CARRERA_ATTR_MIN = 45, CARRERA_ATTR_MAX = 75;   // puntos a repartir entre los cinco atributos (media 60) y tope por atributo
const CARRERA_FAMA = 20;            // fama inicial: apto para todo el Under
const POT_CARRERA = 92;             // potencial del jugador, fijo y oculto
// Entrenamiento del jugador (fase C3b, docs/modo-carrera.md 5.2): un empujón más en el atributo elegido, con el tope de los empujones (pot + BOOST_OVER_POT)
const ENTRENO_JOVEN = 7;            // joven: además del crecimiento normal (calibrado: el activo llega a su primera liga 1,5 temporadas antes que el pasivo sin pasar de 90 a los 10 años)
const ENTRENO_MADUREZ = 1.0;        // madurez: pequeño a propósito, el empujón va en los años jóvenes
const ENTRENO_VETERANO = 0.5;       // veterano: el declive de ese atributo se multiplica por esto
const ENTRENO_REPETICION = 3, ENTRENO_REPETICION_MULT = 0.5;   // el mismo atributo tres años seguidos rinde la mitad desde el tercero
// Fase D1: el entrenamiento se vive por sesiones mensuales y sube el atributo en el momento. 3 entrenos al mes × 12 = la cuota anual de arriba.
const SESIONES_MES = 4, SESIONES_ENTRENO_ANO = 36;
const FATIGA_BATALLA = 8, FATIGA_SESION = 3, FATIGA_DESCANSO = 15, FATIGA_MES_SIN = 10;   // la fatiga del jugador (0-100): sube con batallas y sesiones, baja descansando
const FATIGA_ALTA = 70, FATIGA_BAJA = 30, FATIGA_PENAL = 10, FATIGA_BONUS = 0;             // en la batalla: hasta −10 de nivel efectivo de 70 a 100 (medido sobre 2.000 batallas: con −3 la diferencia de victorias era de 7 puntos y con −6 de 6); sin premio por estar fresco, que daría ventaja a quien no entrena
const SPARRING_GANANCIA = 0.1, SPARRING_TOPE = 1;                                       // sparring: +0,1 de impro y mentalidad por sesión, tope +1 al año
// Fama fuera de las ligas (fase C3a). Quien no está fichado en ninguna liga ya no pierde un punto fijo: su fama tiende hacia su nivel.
const FAMA_BAJA = 0.15;             // si la fama supera el nivel, baja esta fracción de la distancia por temporada (al menos 1 punto)
const FAMA_SUBE = 0.3;              // si la fama está por debajo del nivel, sube esta fracción de la distancia (el nivel acaba haciéndose notar); el mínimo que mantiene la fama del top 100 a ±3 con los torneos
// Fama por torneos (fase C3a), en todos los modos y en el momento de jugarse: sustituye las cifras que Red Bull daba antes (5/2/1 y 10/4/2).
const FAMA_UNDER = [3, 1];          // Under: campeón y finalista
const FAMA_MFU_VICTORIA = 1;        // Monster Fu: por batalla ganada
const FAMA_RB = [6, 3, 2];          // Red Bull nacional: podio
const FAMA_PLAZAS = 3;              // Torneo de Plazas: campeón
const FAMA_RB_INT = [12, 6, 4];     // Red Bull Internacional: podio
const FAMA_CUADRO_VICTORIA = 0.5;   // cada batalla ganada en cualquier cuadro (Red Bull, Plazas, las dos Internacionales y el Under); los medios puntos se guardan en famaResto
function famaSinLiga(f){ const gap=f.nivel-f.fama; const d = gap<0 ? -Math.ceil(-gap*FAMA_BAJA) : Math.round(gap*FAMA_SUBE); return Math.round(clamp(f.fama+d,5,99)); }

function rangeSeeded(rnd, [a, b]){ return a + Math.floor(rnd() * (b - a + 1)); }
// Estima la carrera de un freestyler a partir de nivel, fama y leyenda (misma semilla que los atributos)
function carreraFromStats(f){
  const rnd=seededRandom(seedOf(f.name||'') ^ 0x9E3779B9);
  let exp;
  if(f.custom) exp=rangeSeeded(rnd, EXP_CUSTOM);
  else if(f.legend) exp=rangeSeeded(rnd, EXP_LEGEND);
  else if((f.fama||50)-f.nivel>=EXP_FAMA_GAP) exp=rangeSeeded(rnd, EXP_VETERAN);
  else if(f.nivel-(f.fama||50)>=EXP_NIVEL_GAP) exp=rangeSeeded(rnd, EXP_YOUNG);
  else exp=rangeSeeded(rnd, EXP_MID);
  const marg = exp<=EXP_YOUNG_MAX ? POT_YOUNG : (exp<=EXP_MID_MAX ? POT_MID : POT_VET);
  const pot=Math.min(POT_MAX, f.nivel+rangeSeeded(rnd, marg));
  return {exp, pot};
}
function ensureCarrera(f){ if(!f) return f; if(!f.carrera || typeof f.carrera.exp!=='number' || typeof f.carrera.pot!=='number') f.carrera=carreraFromStats(f); return f; }
function etapaOf(f){ const e=f.carrera ? f.carrera.exp : 5; return e<=EXP_YOUNG_MAX ? 'joven' : (e<=EXP_MID_MAX ? 'madurez' : 'veterano'); }
// Ids que compitieron en la temporada: ligas, Red Bull, Under e Internacional
function competedIds(s){
  const ids=new Set(); const add=x=>{ if(x) ids.add(x); };
  (s.activeKeys||[]).forEach(k=>{ const L=s.leagues[k]; if(L) (L.competitors||[]).forEach(add); });
  if(rbOn(s)){ (s.rb.events||[]).forEach(e=>(e.participants||[]).forEach(add)); if(s.rb.inter) (s.rb.inter.qualifiers||[]).forEach(add); }
  if(s.intl){ (s.intl.qualifiers||[]).forEach(add); if(s.intl.bracket) s.intl.bracket.rounds.flat().forEach(m=>{ add(m.a); add(m.b); }); }
  (s.under||[]).forEach(e=>{ (e.participants||[]).forEach(add); (e.battles||[]).forEach(m=>{ add(m.a); add(m.b); }); });
  return ids;
}
// Evolución de fin de temporada de todos los freestylers. Devuelve [{id, delta}] con el cambio de nivel.
function evolveFreestylers(s){
  const competed=competedIds(s);
  const boost={}; const bump=(id,v)=>{ if(id) boost[id]=(boost[id]||0)+v; };
  (s.activeKeys||[]).forEach(k=>{ const st=(s.leagues[k]&&s.leagues[k].finalStandings)||[]; bump(st[0], BOOST_CHAMPION); bump(st[1], BOOST_RUNNERUP); });
  if(s.intl && s.intl.champion) bump(s.intl.champion, BOOST_INTL);
  const out=[];
  state.freestylers.forEach(f=>{
    if(f.retirado) return;
    ensureAttrs(f); ensureCarrera(f);
    const before=f.nivel; f.attrsPrev={...f.attrs};
    const etapa=etapaOf(f); const exp=f.carrera.exp; const pot=f.carrera.pot;
    // el entrenamiento del jugador se aplica por sesiones durante la temporada (aplicarSesion); aquí ya no hay empujón de cierre
    const ent = null; const entMult=0; const entBonus = 0;
    const d={};
    ATTR_KEYS.forEach(k=>{
      let v=0;
      if(etapa==='joven'){ const marg=Math.max(0, pot-f.attrs[k]); if(marg>0) v=clamp(marg*GROW_RATE*GROW_WEIGHT[k], GROW_MIN, GROW_MAX)*(0.7+Math.random()*0.6); }
      else if(etapa==='madurez'){ v=rnd(-MID_NOISE, MID_NOISE); const marg=Math.max(0, pot-GROW_MID_SLACK-f.attrs[k]); if(marg>0) v+=Math.min(GROW_MID_MAX, marg*GROW_MID_RATE*GROW_WEIGHT[k])*(0.7+Math.random()*0.6); }
      else { const years=exp-EXP_MID_MAX; v=-Math.min(DECLINE_MAX, DECLINE_START+DECLINE_STEP*(years-1))*DECLINE_WEIGHT[k]*(0.7+Math.random()*0.6); if(k===ent) v*=1-(1-ENTRENO_VETERANO)*entMult; }
      if((k==='impro'||k==='mentalidad') && f.attrs[k]<EXP_SUPPORT_CAP) v+=EXP_SUPPORT;
      if(!competed.has(f.id)) v-=INACTIVE_PENALTY;
      d[k]=v;
    });
    const b=boost[f.id]||0;
    ATTR_KEYS.forEach(k=>{
      let nv=f.attrs[k]+d[k];
      if(etapa!=='veterano' && nv>pot && d[k]>0) nv=Math.max(f.attrs[k], pot);   // el crecimiento normal no pasa del potencial
      const bk=b+(k===ent ? entBonus : 0);   // empujones de títulos y entrenamiento: pueden pasar del potencial hasta BOOST_OVER_POT
      nv+=bk; if(bk>0 && nv>pot+BOOST_OVER_POT) nv=Math.max(f.attrs[k], pot+BOOST_OVER_POT);
      f.attrs[k]=clamp(Math.round(nv*10)/10, 1, ATTR_MAX);
    });
    ATTR_KEYS.forEach(k=>f.attrs[k]= f.jugador ? Math.round(f.attrs[k]*10)/10 : Math.round(f.attrs[k]));   // el jugador conserva las décimas de sus sesiones
    const n=nivelFromAttrs(f.attrs);
    if(n<NIVEL_MIN || n>NIVEL_MAX) setNivel(f, clamp(n, NIVEL_MIN, NIVEL_MAX)); else f.nivel=n;
    f.carrera.exp+=1;
    out.push({id:f.id, delta:f.nivel-before});
  });
  return out;
}
// Probabilidad de que un freestyler se retire al cerrar la temporada (crece con la experiencia, baja con el nivel)
function retiroProb(f){
  const e=f.carrera ? f.carrera.exp : 0; if(e<RET_EXP_MIN) return 0;
  let p=RET_BASE + RET_PER_YEAR*(e-RET_EXP_MIN) - RET_NIVEL_SLOPE*(f.nivel-RET_NIVEL_REF);
  if(f.legend) p*=RET_LEGEND_MULT;
  return clamp(p, 0, RET_MAX);
}
// Retiros de fin de temporada. El retirado se queda en el pool con retirado=true (historiales y cuadros lo referencian).
// No se retiran los competidores propios ni los campeones de ese año (ligas e Internacional). Devuelve los ids retirados.
function retirarFreestylers(s){
  const protegidos=new Set();
  (s.activeKeys||[]).forEach(k=>{ const st=(s.leagues[k]&&s.leagues[k].finalStandings)||[]; if(st[0]) protegidos.add(st[0]); });
  if(s.intl && s.intl.champion) protegidos.add(s.intl.champion);
  const out=[];
  state.freestylers.forEach(f=>{
    if(f.retirado || f.custom || f.jugador || protegidos.has(f.id)) return;   // el retiro del jugador lo decide el modo carrera
    if(Math.random()<retiroProb(f)){ f.retirado=true; f.retiradoEn=s.year; out.push(f.id); }
  });
  return out;
}
// Apodos ficticios para los novatos: prefijo + raíz + sufijo, nunca repetidos en el pool (retirados y propios incluidos)
const APODO_PRE = ['Kid', 'MC', 'Lil', 'Big', 'El', 'Don', 'Young', 'Mr.', 'Baby', 'Rey', 'Mini', 'Dr.', 'Sr.'];
const APODO_RAIZ = ['Tizón', 'Nébula', 'Kaos', 'Vórtice', 'Ónix', 'Lúmen', 'Trazo', 'Ébano', 'Zenit', 'Nómada', 'Cráter', 'Sismo', 'Bruma', 'Fénix', 'Kiro', 'Dasz', 'Nicko', 'Verso', 'Rimo', 'Ácido', 'Tinta', 'Ruido', 'Eco', 'Trueke', 'Zarko', 'Mamba', 'Lince', 'Cuervo', 'Búho', 'Sable', 'Tempo', 'Bloke', 'Píxel', 'Neón', 'Sombra', 'Grafo', 'Dardo', 'Flako', 'Gordo', 'Chino', 'Rubio', 'Moreno', 'Pelón', 'Kalo', 'Yeray', 'Nahuel', 'Iker', 'Ulises', 'Dante', 'Lautaro', 'Ciro', 'Bruno', 'Thiago', 'Nazareno', 'Joaco', 'Facu', 'Benja', 'Santi', 'Gael', 'Emi', 'Axel', 'Zaid', 'Ian', 'Noa', 'Kenia', 'Lola', 'Mara', 'Nerea', 'Aitana', 'Vega', 'Candela', 'Yami', 'Ámbar', 'Índigo', 'Grana', 'Cobalto', 'Ocre', 'Jade', 'Cuarzo', 'Basalto', 'Granito', 'Óxido', 'Grafito', 'Titanio', 'Plomo', 'Volt', 'Voltio', 'Amperio', 'Fuzz', 'Static', 'Glitch', 'Pulse', 'Drako', 'Nexo', 'Zeta', 'Delta', 'Omega', 'Sigma', 'Kappa', 'Lambda', 'Theta', 'Dosmil', 'Kilo', 'Mega', 'Tera', 'Siete', 'Nueve', 'Trece', 'Cien', 'Mil', 'Cero', 'Uno', 'Primo', 'Nieto', 'Padrino', 'Sobrino', 'Vecino', 'Alcalde', 'Capitán', 'Teniente', 'Sargento', 'Cadete', 'Monje', 'Fraile', 'Profeta', 'Oráculo', 'Augur', 'Hechizo', 'Conjuro', 'Talismán', 'Amuleto', 'Reliquia', 'Fósil', 'Meteoro', 'Cometa', 'Asteroide', 'Satélite', 'Órbita', 'Eclipse', 'Aurora', 'Crepúsculo', 'Alba', 'Ocaso', 'Marea', 'Oleaje', 'Resaca', 'Espuma', 'Salitre', 'Arena', 'Duna', 'Oasis', 'Espejismo', 'Tundra', 'Taiga', 'Selva', 'Manglar', 'Pantano', 'Ciénaga', 'Lodo', 'Barro', 'Arcilla', 'Yeso', 'Cal', 'Hormigón', 'Asfalto', 'Brea', 'Chapa', 'Hojalata', 'Cobre', 'Latón', 'Bronce', 'Zinc', 'Níquel', 'Cromo'];
const APODO_SUF = ['', '', '', ' MC', ' Jr.', ' One', ' ZK', ' Flow', ' Kid', ' 23', ' 7', ' X'];
function apodoLibre(){
  const usados=new Set(state.freestylers.map(f=>f.name.toLowerCase()));
  for(let i=0;i<500;i++){
    const r=APODO_RAIZ[Math.floor(Math.random()*APODO_RAIZ.length)]; const u=Math.random();
    const name = u<0.35 ? r : (u<0.65 ? APODO_PRE[Math.floor(Math.random()*APODO_PRE.length)]+' '+r : (u<0.85 ? r+APODO_SUF[Math.floor(Math.random()*APODO_SUF.length)] : APODO_PRE[Math.floor(Math.random()*APODO_PRE.length)]+' '+r+APODO_SUF[Math.floor(Math.random()*APODO_SUF.length)]));
    if(!usados.has(name.trim().toLowerCase())) return name.trim();
  }
  let n=2; while(usados.has(('MC '+APODO_RAIZ[0]+' '+n).toLowerCase())) n++; return 'MC '+APODO_RAIZ[0]+' '+n;
}
// Crea un novato de un país: joven, nivel 55-75, fama baja, estilo al azar; unos pocos con potencial alto
function nuevoNovato(country, year){
  const nivel=Math.round(clamp(NOVATO_NIVEL_MEDIA+gauss()*NOVATO_NIVEL_SD, NOVATO_NIVEL[0], NOVATO_NIVEL[1]));
  const exp=rint(NOVATO_EXP[0], NOVATO_EXP[1]);
  const pot = Math.random()<NOVATO_PROMESA ? rint(POT_PROMESA[0], POT_PROMESA[1]) : Math.min(POT_MAX, nivel+rint(POT_NOVATO[0], POT_NOVATO[1]));
  const fama=rint(NOVATO_FAMA[0], NOVATO_FAMA[1]); const keys=Object.keys(STYLES); const style=keys[Math.floor(Math.random()*keys.length)];
  const name=apodoLibre();
  const f={id:uid('f'), name, country, nivel, fama, hype:randHype(fama), style, legend:false, generado:true, debut:year, carrera:{exp, pot}};
  f.attrs=attrsFromNivel(nivel, style, name); f.nivel=nivelFromAttrs(f.attrs);
  return f;
}
// Nuevos talentos de la temporada: uno por retirado en su mismo país, entre NOVATO_MIN y NOVATO_MAX.
// Si faltan países (pocos retiros) se reparten entre los países de las ligas según cuánta gente tienen. Devuelve los ids.
function generarNovatos(s, retirados){
  const n=clamp(retirados.length, NOVATO_MIN, NOVATO_MAX);
  const paises=shuffle(retirados.map(id=>(fby(id)||{}).country).filter(Boolean)).slice(0, n);
  if(paises.length<n){ const bolsa=[]; const liga=new Set(LEAGUES.filter(l=>!l.sbx).flatMap(l=>l.countries||[])); activos().forEach(f=>{ if(liga.has(f.country)) bolsa.push(f.country); });
    while(paises.length<n && bolsa.length) paises.push(bolsa[Math.floor(Math.random()*bolsa.length)]); }
  const out=[]; paises.forEach(c=>{ const f=nuevoNovato(c, s.year); state.freestylers.push(f); out.push(f.id); });
  return out;
}

function styleTag(f){ const st=styleOf(f); return `<span class="style-tag st-${st.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}" title="${esc(STYLES[st].txt)}">${st}</span>`; }
const FOREIGN_MULT = 1.25; // un extranjero cuesta un 25% más por viajes
// país "de liga": casi siempre su nacionalidad. Pirry es cubano pero compite como español (en el resto de ligas, Caribe incluido, cobra viajes)
const HOME_FIX={'Pirry':'España', 'Kevin Mil Problemas':'España'};
function fHome(f){ return (f && HOME_FIX[f.name]) || (f && f.country); }
function isForeign(f, key){ if(isWS(key)) return false; const d=ldef(key); return !!(d && d.countries && !d.countries.includes(fHome(f)) && !(d.noTravel||[]).includes(fHome(f))); }   // isForeign = cobra viaje
const STAR_SALARY = 0.15;  // cada estrella de la empresa: los freestylers piden un 15% más
function contractCost(f, key){ if(isWS(key)) return Math.round(contractCostBase(f,key)*0.5/100)*100; return contractCostBase(f,key); }
function contractCostBase(f, key){ const st=(state.company&&state.company.stars)||0; const nk=(typeof fxVal==='function') ? 1-fxVal(key,'salary') : 1; const base=salaryOf(f)*(1+STAR_SALARY*st)*(isForeign(f,key)?FOREIGN_MULT:1); const capped = Math.min(SALARY_CAP, base); const dj=(isForeign(f,key) && typeof djVal==='function') ? 1-djVal(key,'fcost') : 1; return Math.round(capped*nk*dj/100)*100; }
const SALARY_CAP = 70000;   // nadie cobra más de 70K de sueldo (Walls incluido)
const UQ_SAL = {'Guanyar':2, 'Walls':1.6, 'Wos':1.15, 'Trueno':1.15, 'Duki':1.15, 'TiagoPZK':1.15, 'Jaloner':1.15, 'Lit Killah':1.15};
var SAL_FIXED={'Ibai':50000};   // sueldo fijo de inicio (luego sube con las estrellas, como todos)
function salaryOf(f){
  if(SAL_FIXED[f.name]) return Math.round(Math.min(SALARY_CAP, SAL_FIXED[f.name]*(f.salUp||1))/100)*100;
  const v = 0.6*f.nivel + 0.4*f.fama;
  const raw = (600 + Math.pow(Math.max(0,(v-35))/60, 2.3)*32000) * (f.legend ? LEGEND_MULT : 1) * 0.9 * (UQ_SAL[f.name]||1) * (f.salUp||1);   // salUp: +5% por cada temporada en el top 10 de visitas
  return Math.round(Math.min(SALARY_CAP, raw)/100)*100;
}

