    const epIds=new Set(round.filter(m=>m.ep).map(m=>m.a)); const opts=[]; round.forEach((m,mi)=>{ if(m.ep) return; [m.a,m.b].forEach(id=>{ if(!epIds.has(id)) opts.push([mi,id]); }); }); if(!opts.length) continue;
