        const fA = (fv && nrm(fv)===nrm(A.name)) || (fc && A.country===fc && B.country!==fc) || dS>0, fB = (fv && nrm(fv)===nrm(B.name)) || (fc && B.country===fc && A.country!==fc) || dS<0;
