  const cap=id=>{ const n=fans[id]||0; return n>=10?5:(n>=7?4:(n>=4?3:(n>=2?2:1))); };
  const per={}; const used=new Set();
  const back=new Set(state.seasons.length>1 ? ids.filter(id=>{ const o=luSeasonsOut(id); return o!=null && o>2; }) : []);
