    const fv=(a.fav||[]).map(n=>inLU[nrm(n)]).filter(Boolean), ht=(a.hate||[]).map(n=>inLU[nrm(n)]).filter(Boolean);
    const local=isLocal(a), neutral=!a.country; const opts=[];
