  if(af>=78){ const a=free(); add(a, fill(G(a,'top'),{liga}), 2, END); } else if(af<58){ const a=free(); add(a, fill(G(a,'low'),{liga}), -1, END); }
  // competidores que están de jurado: sus fans querrían verlos competir, sus haters lo celebran
